+/*
+ * Write `len` bytes from `data` to I2C slave `addr7`.
+ * Issues a STOP at the end.
+ */
+static int i2c_write(uint8_t addr7, const uint8_t *data, uint8_t len) {
+    /* Wait for bus idle */
+    for (uint32_t t = 0; t < I2C_TIMEOUT; t++) {
+        if (!(I2C1_ISR & I2C_ISR_BUSY)) break;
+    }
+
+    /* Setup transfer: slave addr, byte count, write direction, generate START */
+    I2C1_CR2 = ((uint32_t)(addr7 << 1) & 0xFEU)  /* SADD[7:1] in bits [7:1] */
+             | ((uint32_t)len << 16)               /* NBYTES */
+             | I2C_CR2_AUTOEND                     /* AUTO STOP */
+             | I2C_CR2_START;                      /* START */
+
+    for (uint8_t i = 0; i < len; i++) {
+        if (i2c_wait(I2C_ISR_TXIS) != 0) return -1;
+        I2C1_TXDR = data[i];
+    }
+
+    /* Wait for STOP (AUTOEND) */
+    if (i2c_wait(I2C_ISR_STOPF) != 0) return -1;
+    I2C1_ICR = I2C_ICR_STOPCF;
+    return 0;
