+static int i2c_read(uint8_t addr7, uint8_t *buf, uint8_t len) {
+    for (uint32_t t = 0; t < I2C_TIMEOUT; t++) {
+        if (!(I2C1_ISR & I2C_ISR_BUSY)) break;
+    }
+
+    I2C1_CR2 = ((uint32_t)(addr7 << 1) & 0xFEU)
+             | ((uint32_t)len << 16)
+             | I2C_CR2_AUTOEND
+             | I2C_CR2_RD_WRN
+             | I2C_CR2_START;
+
+    for (uint8_t i = 0; i < len; i++) {
+        if (i2c_wait(I2C_ISR_RXNE) != 0) return -1;
+        buf[i] = (uint8_t)I2C1_RXDR;
+    }
+
+    if (i2c_wait(I2C_ISR_STOPF) != 0) return -1;
+    I2C1_ICR = I2C_ICR_STOPCF;
+    return 0;
