+/* =========================================================
+ * BMP180 driver
+ * ========================================================= */
+
+#define BMP180_ADDR     0x77U
+#define BMP180_REG_ID   0xD0U
+#define BMP180_CHIP_ID  0x55U
+#define BMP180_REG_CTRL 0xF4U
+#define BMP180_REG_DATA 0xF6U
+#define BMP180_REG_CAL  0xAAU   /* AC1 MSB … MD LSB: 22 bytes */
+
+/* Calibration coefficients */
+typedef struct {
+    int16_t  AC1, AC2, AC3;
+    uint16_t AC4, AC5, AC6;
+    int16_t  B1,  B2;
+    int16_t  MB,  MC,  MD;
+} bmp180_cal_t;
+
+static bmp180_cal_t g_cal;
+
+static int bmp180_read_calibration(void) {
+    uint8_t raw[22];
+    if (i2c_reg_read(BMP180_ADDR, BMP180_REG_CAL, raw, 22) != 0) return -1;
+
+    g_cal.AC1 = (int16_t)((raw[0]  << 8) | raw[1]);
+    g_cal.AC2 = (int16_t)((raw[2]  << 8) | raw[3]);
+    g_cal.AC3 = (int16_t)((raw[4]  << 8) | raw[5]);
+    g_cal.AC4 = (uint16_t)((raw[6]  << 8) | raw[7]);
+    g_cal.AC5 = (uint16_t)((raw[8]  << 8) | raw[9]);
+    g_cal.AC6 = (uint16_t)((raw[10] << 8) | raw[11]);
+    g_cal.B1  = (int16_t)((raw[12] << 8) | raw[13]);
+    g_cal.B2  = (int16_t)((raw[14] << 8) | raw[15]);
+    g_cal.MB  = (int16_t)((raw[16] << 8) | raw[17]);
+    g_cal.MC  = (int16_t)((raw[18] << 8) | raw[19]);
+    g_cal.MD  = (int16_t)((raw[20] << 8) | raw[21]);
+    return 0;
+}
+
+/* Read uncompensated temperature */
+static int bmp180_read_ut(int32_t *ut) {
+    uint8_t cmd = 0x2E;  /* temp measurement */
+    uint8_t buf[2];
+    if (i2c_write(BMP180_ADDR, (uint8_t[]){BMP180_REG_CTRL, cmd}, 2) != 0) return -1;
+    delay_ms(5);  /* conversion time ≤ 4.5 ms */
+    if (i2c_reg_read(BMP180_ADDR, BMP180_REG_DATA, buf, 2) != 0) return -1;
+    *ut = (int32_t)((buf[0] << 8) | buf[1]);
+    return 0;
+}
+
+/* Read uncompensated pressure, OSS=3 (ultra-high resolution) */
+#define BMP180_OSS 3
+static int bmp180_read_up(int32_t *up_val) {
+    uint8_t cmd = (uint8_t)(0x34 + (BMP180_OSS << 6));
+    uint8_t buf[3];
+    if (i2c_write(BMP180_ADDR, (uint8_t[]){BMP180_REG_CTRL, cmd}, 2) != 0) return -1;
+    delay_ms(26);  /* OSS=3: max 25.5 ms */
+    if (i2c_reg_read(BMP180_ADDR, BMP180_REG_DATA, buf, 3) != 0) return -1;
+    *up_val = (int32_t)(((uint32_t)buf[0] << 16 |
+                         (uint32_t)buf[1] <<  8 |
+                         (uint32_t)buf[2]) >> (8 - BMP180_OSS));
+    return 0;
+}
+
+/*
+ * BMP180 datasheet §4.1.4 compensation algorithm.
+ * Returns temperature in 0.1 °C, pressure in Pa.
+ */
+static void bmp180_compensate(int32_t ut, int32_t up_raw,
+                               int32_t *t_out, int32_t *p_out) {
+    int32_t X1, X2, B5, B6, X3, B3, p;
+    uint32_t B4, B7;
+
+    /* Temperature */
+    X1 = ((ut - (int32_t)g_cal.AC6) * (int32_t)g_cal.AC5) >> 15;
+    X2 = ((int32_t)g_cal.MC << 11) / (X1 + (int32_t)g_cal.MD);
+    B5 = X1 + X2;
+    *t_out = (B5 + 8) >> 4;   /* units: 0.1 °C */
+
+    /* Pressure */
+    B6 = B5 - 4000;
+    X1 = ((int32_t)g_cal.B2 * ((B6 * B6) >> 12)) >> 11;
+    X2 = ((int32_t)g_cal.AC2 * B6) >> 11;
+    X3 = X1 + X2;
+    B3 = ((((int32_t)g_cal.AC1 * 4 + X3) << BMP180_OSS) + 2) >> 2;
+    X1 = ((int32_t)g_cal.AC3 * B6) >> 13;
+    X2 = ((int32_t)g_cal.B1 * ((B6 * B6) >> 12)) >> 16;
+    X3 = ((X1 + X2) + 2) >> 2;
+    B4 = ((uint32_t)g_cal.AC4 * (uint32_t)(X3 + 32768)) >> 15;
+    B7 = ((uint32_t)(up_raw - B3) * (uint32_t)(50000 >> BMP180_OSS));
+    if (B7 < 0x80000000UL) {
+        p = (int32_t)((B7 * 2) / B4);
+    } else {
+        p = (int32_t)((B7 / B4) * 2);
+    }
+    X1 = (p >> 8) * (p >> 8);
+    X1 = (X1 * 3038) >> 16;
+    X2 = (-7357 * p) >> 16;
+    *p_out = p + ((X1 + X2 + 3791) >> 4);
+}
